<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class LocalRegulationController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 public function index(Request $r){$this->ok($r);$docs=DB::table('local_regulations')->orderByDesc('effective_from')->orderByDesc('id')->get();$rules=DB::table('academic_rules as ar')->leftJoin('local_regulations as lr','lr.id','=','ar.local_regulation_id')->select('ar.*','lr.title as regulation_title','lr.document_number')->orderBy('ar.category')->orderBy('ar.name')->get();return view('academic-office.regulations',compact('docs','rules'));}
 public function store(Request $r){$this->ok($r);$d=$r->validate(['code'=>'nullable|string|max:100','title'=>'required|string|max:500','document_number'=>'nullable|string|max:100','approved_on'=>'nullable|date','effective_from'=>'nullable|date','effective_to'=>'nullable|date|after_or_equal:effective_from','version'=>'required|integer|min:1','status'=>'required|in:draft,active,archived','note'=>'nullable|string|max:5000']);DB::table('local_regulations')->insert($d+['created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Локальный акт добавлен.');}
 public function rule(Request $r){$this->ok($r);$d=$r->validate(['local_regulation_id'=>'nullable|exists:local_regulations,id','key'=>'required|string|max:150|unique:academic_rules,key','name'=>'required|string|max:255','category'=>'required|in:attestation,practice,workload,gia,graduation,curriculum,other','value_type'=>'required|in:integer,decimal,boolean,string','value'=>'required|string|max:1000','description'=>'nullable|string|max:3000']);DB::table('academic_rules')->insert($d+['enabled'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Правило добавлено.');}
 public function updateRule(Request $r,$id){$this->ok($r);$x=DB::table('academic_rules')->find($id);abort_if(!$x,404);$d=$r->validate(['value'=>'required|string|max:1000','enabled'=>'required|boolean']);DB::table('academic_rules')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Правило обновлено.');}
}